                }
                if (leftPos < 10) {
                    leftPos = 10;
                }

                // Keep the little pointer arrow pointed exactly at the icon
                var arrowPos = iconCenter - leftPos;
                if (arrowPos < 10) arrowPos = 10;
                if (arrowPos > ttWidth - 10) arrowPos = ttWidth - 10;

