    if ($atts['campus'] !== 'all') {
        $campus_mapping = array(
            'chaofah'     => 'Chaofah',
            'cherngtalay' => 'Cherngtalay'
        );
        $campus_name = isset($campus_mapping[$atts['campus']]) ? $campus_mapping[$atts['campus']] : 'Both Campuses';

        $args['tax_query'] = array(
            'relation' => 'OR',
            array(
                'taxonomy' => 'staff_campus',
                'field'    => 'name',
                'terms'    => $campus_name
            ),
            array(
                'taxonomy' => 'staff_campus',
                'field'    => 'name',
                'terms'    => 'Both Campuses'
            )
        );
    }

    $query = new WP_Query($args);
    $avatars_html = '';
