/**
 * Load Magnific Popup on imported archive posts.
 *
 * Divi 5 enqueues the library only when its own detection finds a lightbox
 * module in the layout. Imported weeklies are raw HTML in the standard content
 * area, so it never arrives and the Weekly Update V2 popup init — which is
 * guarded by `if ($.fn.magnificPopup)` — skips silently. A click on a gallery
 * image then opens the raw JPEG.
 *
 * Add the extracted-posts type to is_singular() once it exists.
 */

add_action('wp_enqueue_scripts', function () {
    if (!is_singular(['weekly_update', 'post'])) {
        return;
    }

    if (class_exists('\ET\Builder\FrontEnd\Assets\DynamicAssetsUtils')) {
        \ET\Builder\FrontEnd\Assets\DynamicAssetsUtils::enqueue_magnific_popup_script();
    }

    wp_enqueue_style(
        'magnific-popup',
        get_template_directory_uri() . '/includes/builder/feature/dynamic-assets/assets/css/magnific_popup.css',
        [],
        ET_CORE_VERSION
    );
}, 20);

/**
 * Plugin/Snippet Name: Strip Image Titles & Captions
 * Description: Adds a tool under Media to bulk remove titles, captions, and descriptions from images. Also auto-strips on new uploads.
 */

// ==========================================
// 1. AUTO STRIP ON UPLOAD
// ==========================================
add_filter( 'wp_insert_attachment_data', 'agy_auto_strip_image_captions', 10, 2 );
function agy_auto_strip_image_captions( $data, $postarr ) {
    // Check if the upload is an attachment and specifically an image.
    // This filter also fires when an existing image is edited/saved, so only strip
    // brand-new uploads (no ID yet). Titles/captions added later in the Media Library are kept.
    if ( empty( $postarr['ID'] ) && $data['post_type'] === 'attachment' && strpos( $data['post_mime_type'], 'image/' ) === 0 ) {
        // Clear the title, excerpt (caption), and content (description)
        $data['post_title']   = '';
        $data['post_excerpt'] = '';
        $data['post_content'] = '';
    }
    return $data;
}

