// Render Page and Handle Logic
function agy_strip_captions_page() {
    if (!current_user_can('manage_options')) {
        return;
    }

    $step = isset($_GET['step']) ? intval($_GET['step']) : 0;
    $include_cat = isset($_GET['include_cat']) ? intval($_GET['include_cat']) : 0;
    $exclude_cat = isset($_GET['exclude_cat']) ? intval($_GET['exclude_cat']) : 0;

    echo '<div class="wrap">';
    echo '<h1>Bulk Strip Image Titles & Captions</h1>';

    if ($step > 0) {
        // Processing Step (Batch of 200)
        $args = array(
            'post_type'      => 'attachment',
            'post_mime_type' => 'image',
            'post_status'    => 'inherit',
            'posts_per_page' => 200,
            'paged'          => $step,
            'fields'         => 'ids' // Only get IDs for performance
        );

        $tax_query = array();

        // Add inclusion logic
        if ($include_cat > 0) {
            $tax_query[] = array(
                'taxonomy' => 'attachment-category', 
                'field'    => 'term_id',
                'terms'    => $include_cat,
                'operator' => 'IN',
            );
        }

        // Add exclusion logic
        if ($exclude_cat > 0) {
            $tax_query[] = array(
                'taxonomy' => 'attachment-category', 
                'field'    => 'term_id',
                'terms'    => $exclude_cat,
                'operator' => 'NOT IN',
            );
        }

        if (!empty($tax_query)) {
            $args['tax_query'] = $tax_query;
        }

        $query = new WP_Query($args);

        if ($query->have_posts()) {
            foreach ($query->posts as $post_id) {
                // Update post to remove title, excerpt (caption), and content (description)
                wp_update_post(array(
                    'ID'           => $post_id,
                    'post_title'   => '',
                    'post_excerpt' => '',
                    'post_content' => ''
                ));
            }

            $next_step = $step + 1;
