        array( 'type' => 'chips', 'h' => 'Globally Recognised &amp; Accredited', 'items' => array( '!ISQM Gold', 'Cambridge International', 'FOBISIA Member', 'White Rose Maths Champion School', 'Pearson Edexcel Approved', 'Duke of Edinburgh’s Award' ) ),
